// Tape sections of the two production mannequin meshes, read by the pattern
// builders. The numbers live in body-sections-data.mjs, generated by
// tools/reshape-anatomy.py together with the meshes themselves, so the cloth is
// always cut for the body it is drawn on.
import {sections, landmarks, sectionBase, widthKnots} from './body-sections-data.mjs?v=2026-11-24o';

// Cross sections are sampled every 10 mm from the crotch upward. Each row holds
// rx, rz, cz and the hull perimeter, then the radial distance every 5 degrees
// from the front; all in half millimetres.
function sectionSample(rows, base, y) {
  const index = Math.max(0, Math.min(rows.length - 1, (y - base) * 100));
  const lower = Math.floor(index);
  return [rows[lower], rows[Math.min(lower + 1, rows.length - 1)], index - lower];
}

const interpolate = (a, b, t) => a + (b - a) * t;
const unit = 0.0005;

function buildModel(model) {
  const rows = sections[model], base = sectionBase[model];
  return {
    ...landmarks[model],
    base,
    bodyAt(y) {
      const [a, b, t] = sectionSample(rows, base, y);
      return {
        rx: unit * interpolate(a[0], b[0], t),
        rz: unit * interpolate(a[1], b[1], t),
        cz: unit * interpolate(a[2], b[2], t),
        perimeter: unit * interpolate(a[3], b[3], t)
      };
    },
    // Cast from (0, bodyAt(y).cz). Zero radians is +Z and pi/2 is +X.
    radialAt(y, angle) {
      const [a, b, t] = sectionSample(rows, base, y);
      const theta = Math.abs(Math.atan2(Math.sin(angle), Math.cos(angle)));
      const index = theta * 36 / Math.PI;
      const lo = Math.floor(index);
      const hi = Math.min(36, lo + 1);
      const f = index - lo;
      const r0 = interpolate(a[4 + lo], a[4 + hi], f);
      const r1 = interpolate(b[4 + lo], b[4 + hi], f);
      return unit * interpolate(r0, r1, t);
    }
  };
}

const avatars = { female: buildModel('female'), male: buildModel('male') };
export function getAvatarFit(model) {
  return avatars[model === 'male' ? 'male' : 'female'];
}

// The horizontal profile the meshes were shaped with, as a function of a height
// in the source mesh. The rig is authored in that frame, so it asks here for the
// width its own coordinates already carry.
function knots(points) {
  return y => {
    if (y <= points[0][0]) return points[0][1];
    for (let i = 1; i < points.length; i++) {
      if (y <= points[i][0]) {
        const [a, p] = points[i - 1], [b, q] = points[i];
        const t = (y - a) / (b - a);
        return p + (q - p) * t * t * (3 - 2 * t);
      }
    }
    return points[points.length - 1][1];
  };
}
const widths = { female: knots(widthKnots.female), male: knots(widthKnots.male) };
export function bodyWidth(model, y) {
  return widths[model === 'male' ? 'male' : 'female'](y);
}
